edits.newText:
buildscript {
	repositories {
		mavenCentral()
	}
	dependencies {
		classpath "org.owasp:dependency-check-gradle:9.0.9"
	}
}

plugins {
	id 'java'
	id 'org.springframework.boot' version '4.1.0'
	id 'io.spring.dependency-management' version '1.1.7'
	id 'com.github.ben-manes.versions' version '0.54.0'
}

group = 'com.example'
version = '0.0.1-SNAPSHOT'

java {
	toolchain {
		languageVersion = JavaLanguageVersion.of(21)
	}
}

repositories {
	mavenCentral()
}

ext {
	set('springAiVersion', "2.0.0")
}

dependencies {
	implementation 'org.springframework.boot:spring-boot-starter-web'
	implementation 'org.springframework.boot:spring-boot-starter-amqp'
	implementation 'com.fasterxml.jackson.core:jackson-databind:2.18.4'
	implementation 'org.aspectj:aspectjweaver:1.9.25.1'
	implementation 'org.springframework.ai:spring-ai-starter-model-ollama'
	implementation 'org.jsoup:jsoup:1.23.1'
	implementation 'com.drewnoakes:metadata-extractor:2.21.0'
	implementation 'org.springframework.boot:spring-boot-starter-actuator'
	implementation 'io.micrometer:micrometer-registry-prometheus:1.15.0'
	testImplementation 'org.springframework.boot:spring-boot-starter-webmvc-test'
	testImplementation 'org.springframework.boot:spring-boot-starter-test'
	testRuntimeOnly 'org.junit.platform:junit-platform-launcher:6.1.2'
}

dependencyManagement {
	imports {
		mavenBom "org.springframework.ai:spring-ai-bom:${springAiVersion}"
	}
}

tasks.named('test') {
	useJUnitPlatform()
}

// Use the plugin from the buildscript classpath
apply plugin: 'org.owasp.dependencycheck'

dependencyCheck {
	autoUpdate = false
	data.directory = "build/nvd-data"
	outputDirectory = "build/reports/dependency-check"
	format = "HTML"
	suppressionFile = 'config/dependency-check-suppression.xml'
}

